    washer: { ratio: "600/850", glass: { x: 49.67, y: 41.41, w: 62, h: 43.76, r: "50%" }, ring: { x: 49.67, y: 41.41, d: 79.3 }, lcd: { x: 62.33, y: 1.18, w: 31.83, h: 7.53 },
              wifi: { x: 6, y: 15.3 }, door: { x: 6, y: 74 } },
    dryer:  { ratio: "600/850", glass: { x: 49.67, y: 41.41, w: 64, h: 45.18, r: "50%" }, ring: { x: 49.67, y: 41.41, d: 81.3 }, lcd: { x: 62.67, y: 2.59, w: 31.33, h: 7.76 },
              wifi: { x: 6, y: 16 }, door: { x: 6, y: 70 } },
